import { useState, useCallback, useEffect } from 'react'

/**
 * Persists a reorderable list order in localStorage.
 * applyOrder() sorts the given items by the saved order.
 * setOrder() replaces the saved order.
 */
export function useOrderPreference(storageKey: string) {
  const [order, setOrder] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem(storageKey)
      return saved ? JSON.parse(saved) : []
    } catch {
      return []
    }
  })

  useEffect(() => {
    try {
      localStorage.setItem(storageKey, JSON.stringify(order))
    } catch { /* storage full or unavailable */ }
  }, [storageKey, order])

  const applyOrder = useCallback(
    <T extends string>(items: T[]): T[] => {
      const orderMap = new Map(order.map((id, i) => [id, i]))
      const ordered = [...items].sort((a, b) => {
        const ai = orderMap.get(a as string)
        const bi = orderMap.get(b as string)
        if (ai !== undefined && bi !== undefined) return ai - bi
        if (ai !== undefined) return -1
        if (bi !== undefined) return 1
        return 0
      })
      return ordered
    },
    [order]
  )

  return { order, setOrder, applyOrder } as const
}