import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'

export interface DashboardWidgetConfig {
  id: string
  labelKey: string
  defaultLabel: string
  enabled: boolean
}

interface DashboardWidgetsState {
  widgets: DashboardWidgetConfig[]
  setWidgets: (widgets: DashboardWidgetConfig[]) => void
  toggleWidget: (id: string) => void
  resetToDefaults: () => void
}

const defaultWidgets: DashboardWidgetConfig[] = [
  { id: 'stats', labelKey: 'dashboard.widgets.stats', defaultLabel: 'Statistics', enabled: true },
  { id: 'traffic', labelKey: 'dashboard.widgets.traffic', defaultLabel: 'Traffic', enabled: true },
  { id: 'connections', labelKey: 'dashboard.widgets.connections', defaultLabel: 'Connections', enabled: true },
  { id: 'load', labelKey: 'dashboard.widgets.load', defaultLabel: 'Node Load', enabled: true },
  { id: 'activity', labelKey: 'dashboard.widgets.activity', defaultLabel: 'Activity', enabled: true },
  { id: 'system', labelKey: 'dashboard.widgets.system', defaultLabel: 'System', enabled: true },
]

export const useDashboardWidgetsStore = create<DashboardWidgetsState>()(
  persist(
    (set) => ({
      widgets: [...defaultWidgets],

      setWidgets: (widgets) => set({ widgets }),
      toggleWidget: (id) =>
        set((state) => ({
          widgets: state.widgets.map((w) =>
            w.id === id ? { ...w, enabled: !w.enabled } : w
          ),
        })),
      resetToDefaults: () => set({ widgets: [...defaultWidgets] }),
    }),
    {
      name: 'hexaveil-dashboard-widgets',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        widgets: state.widgets,
      }),
    }
  )
)