import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { GripVertical } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SortableSectionProps {
  id: string
  children: React.ReactNode
  className?: string
  header?: React.ReactNode
}

export function SortableSection({ id, children, className, header }: SortableSectionProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        'relative group rounded-xl glass-heavy',
        isDragging && 'opacity-50 ring-2 ring-primary/40',
        className
      )}
    >
      {/* Drag handle */}
      <div
        {...attributes}
        {...listeners}
        className="absolute top-0 left-0 right-0 h-8 cursor-grab active:cursor-grabbing flex items-center justify-center text-dark-300 hover:text-primary-400 opacity-0 group-hover:opacity-100 transition-opacity z-10"
      >
        <GripVertical className="w-4 h-4" />
      </div>

      {/* Optional custom header */}
      {header && (
        <div className="pt-3 px-5">
          {header}
        </div>
      )}

      {/* Content */}
      <div className={cn(header ? 'pb-4 px-5' : 'p-5')}>
        {children}
      </div>
    </div>
  )
}